const raw = $json;
const type = raw.update_type;

let max_user_id = null;
let username = null;
let first_name = null;
let last_name = null;
let chat_id = null;
let message_id = null;
let text = null;
let callback_payload = null;
let callback_query_id = null;
let forward_chat_id = null;
let is_channel = null;
let normalizedType = 'unknown';


if (type === 'message_created' || type === 'message_chat_created') {
  normalizedType = 'message';
  max_user_id = raw.message?.sender?.user_id ?? null;
  username = raw.message?.sender?.username ?? null;
  first_name = raw.message?.sender?.first_name ?? null;
  last_name = raw.message?.sender?.last_name ?? null;
  chat_id = String(raw.message?.recipient?.chat_id ?? '');
  message_id = raw.message?.body?.mid ?? null;
  text = raw.message?.body?.text ?? null;
  if (raw.message?.link?.type === 'forward') {
    forward_chat_id = raw.message?.link?.chat_id ?? null;
  }
} else if (type === 'message_callback') {
  normalizedType = 'callback';
  max_user_id = raw.callback?.user?.user_id ?? null;
  username = raw.callback?.user?.username ?? null;
  first_name = raw.callback?.user?.first_name ?? null;
  last_name = raw.callback?.user?.last_name ?? null;
  chat_id = String(raw.message?.recipient?.chat_id ?? '');
  message_id = raw.message?.body?.mid ?? null;
  callback_payload = raw.callback?.payload ?? null;
  callback_query_id = raw.callback?.callback_id ?? null;
} else if (type === 'bot_started') {
  normalizedType = 'bot_started';
  max_user_id = raw.user?.user_id ?? null;
  username = raw.user?.username ?? null;
  first_name = raw.user?.first_name ?? null;
  last_name = raw.user?.last_name ?? null;
  chat_id = String(raw.chat_id ?? '');
} else if (type === 'bot_added') {
  normalizedType = 'bot_added';
  max_user_id = raw.user?.user_id ?? null;
  chat_id = String(raw.chat_id ?? '');
  is_channel = raw.is_channel ?? false;
} else if (type === 'bot_removed') {
  normalizedType = 'bot_removed';
  max_user_id = raw.user?.user_id ?? null;
  chat_id = String(raw.chat_id ?? '');
  is_channel = raw.is_channel ?? false;
}

// Если нет отправителя — игнорируем (канальный пост)
if (!max_user_id) {
  return { json: { type: 'unknown', max_user_id: null } };
}

return {
  json: {
    type: normalizedType,
    max_user_id,
    username,
    first_name,
    last_name,
    chat_id,
    message_id,
    text,
    callback_payload,
    callback_query_id,
    forward_chat_id,
    is_channel,
    raw
  }
};

