const n = $json.normalized;
const s = $json.session;
let route = 'flow';

// Глобальный перехват nav_menu (любой шаг, только если user уже есть)
if (n.type === 'callback' && n.callback_payload === 'nav_menu' && s.user_id) {
  return { json: { ...$json, route: 'main_menu' } };
}

if (s.current_step === 'COMPLETED') {
  route = 'main_menu';
} else if (n.type === 'message' && n.text === '/start') {
  route = s.current_step === 'START' ? 'flow' : 'resume';
}
return { json: { ...$json, route } };

const session = $json.session;
const normalized = $json.normalized;
const step = session.current_step;
const type = normalized.type; // 'message' | 'callback'
const text = normalized.text || '';
const payload = normalized.callback_payload || '';

const stepExpects = {
  'START':                    'callback',
  'CHANNEL_FORWARD_REQUEST':  'message',
  'PROMPT_CENSOR_INPUT':      'message',
  'PROMPT_EDITOR_INPUT':      'message',
  'TIMEZONE_PICK':            'callback',
  'POSTING_HOURS_INPUT':      'message',
  'POSTING_HOURS_CONFIRM':    'callback',
  'SOURCES_INPUT':            'message_or_callback',
  'SOURCES_FULL':             'message_or_callback',
  'COMPLETED':                'callback',
  'SUPPORT_INPUT':            'message',
};

const expected = stepExpects[step];
let handler;

// Спецкейс: retry_forward
if (step === 'CHANNEL_FORWARD_REQUEST' && type === 'callback' && payload === 'retry_forward') {
  return { ...$json, handler: 'reshow' };
}

// Спецкейс: текст на экране подтверждения часов → переразбираем как новый ввод
if (step === 'POSTING_HOURS_CONFIRM' && type === 'message') {
  return { ...$json, handler: 'POSTING_HOURS_INPUT' };
}
// FINAL_SAVE — транзиентный экран «Завершаем…»
if (step === 'FINAL_SAVE') {
  return { ...$json, handler: 'FINALIZE_RETRY' };
}

if (!expected) {
  handler = 'reshow';
} else if (expected === 'message_or_callback') {
  handler = step;
} else if (expected === type) {
  handler = step;
} else if (type === 'callback') {
  handler = 'ignore';
} else {
  handler = 'reshow';
}
// SOURCES_FULL — это вид шага SOURCES_INPUT; роутим в тот же обработчик
if (handler === 'SOURCES_FULL') handler = 'SOURCES_INPUT';
return { ...$json, handler };

return { ...$json, handler };

