const session = $json.session;
const normalized = $json.normalized;
const text = (normalized.text || '').trim();

let reason = 'valid';

if (text.length < 1) {
  reason = 'too_short';
} else if (text.length > 500) {
  reason = 'too_long';
} else {
  const blocklist = [
    /ignore\s+previous/i,
    /system\s*:/i,
    /<\/prompt>/i,
    /\{\{/,
    /<\|[^|]*\|>/,
    /###/,
    /забудь/i,
    /новая\s+роль/i,
    /system\s+prompt/i,
    /(.)\1{20,}/,
    /[^\x09\x0A\x0D\x20-\x7E\u00A0-\uFFFF]/
  ];
  for (const pattern of blocklist) {
    if (pattern.test(text)) {
      reason = 'forbidden';
      break;
    }
  }
}

const current_step = session.current_step;
let save_key, next_step, error_key;

if (current_step === 'PROMPT_CENSOR_INPUT') {
  save_key  = 'censor_prompt';
  next_step = 'PROMPT_EDITOR_INPUT';
} else {
  save_key  = 'editor_prompt';
  next_step = 'TIMEZONE_PICK';
}

if      (reason === 'too_short') error_key = 'TXT_PROMPT_EMPTY';
else if (reason === 'too_long')  error_key = 'TXT_PROMPT_TOO_LONG';
else if (reason === 'forbidden') error_key = 'TXT_PROMPT_FORBIDDEN';
else                             error_key = '';

return {
  json: {
    session,
    normalized,
    route:    $json.route,
    handler:  $json.handler,
    _valid:   reason === 'valid',
    _reason:  reason,
    _error_key: error_key,
    _save_key:  save_key,
    _next_step: next_step,
    text,
  }
};

