const session    = $json.session;
const normalized = $json.normalized;
const raw = normalized.text;

if (!raw || typeof raw !== 'string') {
  return { json: { session, normalized, _valid: false, _reason: 'invalid', _error_key: 'TXT_HOURS_INVALID', hours_string: null, hours_display: null } };
}

const fragments = raw.split(/[\n,]+/).map(s => s.trim()).filter(Boolean);

const parsed = [];
for (const frag of fragments) {
  const m = frag.match(/(\d{2})[ :]?(\d{2})/);
  if (!m) continue;
  const hh = parseInt(m[1], 10);
  const mm = parseInt(m[2], 10);
  if (hh > 23 || mm > 59) continue;
  const t = String(hh).padStart(2,'0') + ':' + String(mm).padStart(2,'0');
  parsed.push(t);
}

// Дедуп + сортировка
const unique = [...new Set(parsed)].sort();

let _valid = false, _reason = null, _error_key = null;

if (unique.length === 0) {
  _reason = 'invalid';
  _error_key = 'TXT_HOURS_INVALID';
} else if (unique.length > 24) {
  _reason = 'too_many';
  _error_key = 'TXT_HOURS_TOO_MANY';
} else {
  _valid = true;
}

return { json: {
  session,
  normalized,
  _valid,
  _reason,
  _error_key,
  hours_string:  _valid ? unique.join(',') : null,
  hours_display: _valid ? unique.join(', ') : null,
} };

const session    = $json.session;
const normalized = $json.normalized;
const p = normalized.callback_payload;

const _route = p === 'posting_hours_confirm' ? 'confirm'
             : p === 'posting_hours_redo'    ? 'redo'
             : 'ignore';

return { json: { session, normalized, _route } };

const norm = $json.normalized ?? {};
const session = $json.session ?? {};
const ctx = session.context ?? {};

const type = norm.type ?? null;
const text = norm.text ?? null;
const payload = norm.callback_payload ?? null;
const sources = ctx.sources ?? [];
const pending = ctx.pending_source ?? null;

let action;

if (type === 'callback' && typeof payload === 'string') {
  if (payload === 'sources_done') {
    action = 'done';
  } else if (payload.startsWith('source_approve:')) {
    action = 'approve';
  } else if (payload.startsWith('source_skip:')) {
    action = 'skip';
  } else {
    action = 'ignore';
  }
} else if (type === 'message') {
  if (text === null) {
    action = 'add';
  } else if (pending !== null) {
    action = 'busy';
  } else {
    action = 'add';
  }
} else {
  action = 'ignore';
}

return {
  json: {
    session_id: session.id,
    chat_id: norm.chat_id,
    max_user_id: norm.max_user_id,
    type: type,
    text: text,
    callback_payload: payload,
    context: ctx,
    handler: $json.handler,
    _action: action
  }
};

