const text = $json.text ?? '';
const ctx = $json.context ?? {};
const sources = ctx.sources ?? [];

if (text === null || text === '') {
  return { json: { ...$json, _valid: false, _error_key: 'INVALID', token: null, canon_url: null } };
}

// PRIVATE-детект — до нормализации, по структуре ссылки
const privatePatterns = [/t\.me\/\+/i, /t\.me\/joinchat\//i, /t\.me\/c\//i];
if (privatePatterns.some(p => p.test(text))) {
  return { json: { ...$json, _valid: false, _error_key: 'PRIVATE', token: null, canon_url: null } };
}

let raw = text.trim();
const parts = raw.split(/[\s\n]+/);
if (parts.length > 1) { raw = parts[0]; }

raw = raw
  .replace(/^https?:\/\//i, '')
  .replace(/^telegram\.me\//i, '')
  .replace(/^t\.me\/s\//i, '')
  .replace(/^t\.me\//i, '')
  .replace(/^@/, '');

raw = raw.split('/')[0];

// SSRF whitelist
const originalLower = text.toLowerCase();
const forbiddenPatterns = [
  /https?:\/\/127\./,
  /https?:\/\/169\.254\./,
  /https?:\/\/192\.168\./,
  /https?:\/\/10\./,
  /https?:\/\/localhost/,
  /https?:\/\/\d+\.\d+\.\d+\.\d+/
];
for (const pattern of forbiddenPatterns) {
  if (pattern.test(originalLower)) {
    return { json: { ...$json, _valid: false, _error_key: 'INVALID', token: null, canon_url: null } };
  }
}

// Charset: a-z0-9_ длиной 5–32
const token = raw.toLowerCase();
if (!/^[a-z0-9_]{5,32}$/.test(token)) {
  return { json: { ...$json, _valid: false, _error_key: 'INVALID', token: null, canon_url: null } };
}

const canon_url = `https://t.me/s/${token}`;

if (sources.length >= 10) {
  return { json: { ...$json, _valid: false, _error_key: 'LIMIT', token, canon_url } };
}

const isDup = sources.some(s => s.url === canon_url);
if (isDup) {
  return { json: { ...$json, _valid: false, _error_key: 'DUP', token, canon_url } };
}

return { json: { ...$json, _valid: true, _error_key: null, token, canon_url, _has_multiple: parts.length > 1 } };

