const html = $json.data ?? $json.body ?? '';
const token = $('OM: CODE Validate Source URL').first().json.token;

// 1. Живость — ищем маркер
const alive = html.includes('tgme_widget_message');

if (!alive) {
  return {
    json: {
      ...$('OM: CODE Validate Source URL').first().json,
      _checking_mid: $('OM: MAX Send Checking Msg').first().json.message?.body?.mid ?? null,
      alive: false,
      oldest_id: null,
      newest_id: null,
      last_processed_id: null,
      subs: null,
      posts_week: null,
      last_post_date: null,
      _class: 'dead'
    }
  };
}

// 2. ID постов — только data-post="<token>/<N>"
const postIdRegex = new RegExp(`data-post="${token}/(\\d+)"`, 'g');
const ids = [];
let m;
while ((m = postIdRegex.exec(html)) !== null) {
  const n = parseInt(m[1], 10);
  if (n > 0 && n < 100000000) ids.push(n);
}
const oldest_id = ids.length > 0 ? Math.min(...ids) : null;
const newest_id = ids.length > 0 ? Math.max(...ids) : null;
const last_processed_id = oldest_id !== null ? oldest_id - 1 : 0;

// 3. Подписчики
let subs = null;
const subsMatch = html.match(/tgme_channel_info_counter[^>]*>[\s\S]*?<span[^>]*>([\d\s,KkMm\.]+)<\/span>[\s\S]*?subscriber/i);
if (subsMatch) {
  subs = subsMatch[1].trim();
}

// 4. Активность — посты за последние 7 дней
const now = Date.now();
const sevenDaysMs = 7 * 24 * 60 * 60 * 1000;
const dateRegex = /datetime="([^"]+)"/g;
let posts_week = 0;
let last_post_date = null;
let dm;
while ((dm = dateRegex.exec(html)) !== null) {
  const d = new Date(dm[1]);
  if (!isNaN(d.getTime())) {
    if ((now - d.getTime()) <= sevenDaysMs) {
      posts_week++;
    }
    if (!last_post_date || d > new Date(last_post_date)) {
      last_post_date = dm[1];
    }
  }
}

// 5. Классификация
const _class = posts_week < 3 ? 'stale' : 'ok';

return {
  json: {
    ...$('OM: CODE Validate Source URL').first().json,
    _checking_mid: $('OM: MAX Send Checking Msg').first().json.message?.body?.mid ?? null,
    alive: true,
    oldest_id,
    newest_id,
    last_processed_id,
    subs,
    posts_week,
    last_post_date,
    _class
  }
};

const payload = $json.callback_payload ?? '';
const context  = $json.context ?? {};
const session_id = Number($json.session_id);
const _cnt = Array.isArray(context.sources) ? context.sources.length : 0;

let token  = null;
let action = 'ignore';

if (payload.startsWith('source_approve:')) {
  token  = payload.slice('source_approve:'.length).trim().toLowerCase();
  action = 'approve';
} else if (payload.startsWith('source_skip:')) {
  token  = payload.slice('source_skip:'.length).trim().toLowerCase();
  action = 'skip';
}

if (!token) return { json: { _action: 'ignore', session_id, sources_count: _cnt } };

const pending = context.pending_source;
if (!pending) return { json: { _action: 'ignore', session_id, sources_count: _cnt } };

const canon_url = `https://t.me/s/${token}`;
if (pending.url !== canon_url) return { json: { _action: 'ignore', session_id, sources_count: _cnt } };

const sources = Array.isArray(context.sources) ? context.sources : [];

return {
  json: {
    _action:          action,
    token,
    canon_url,
    session_id,
    sources_count:    sources.length,
    last_processed_id: pending.last_processed_id,
    subs:              pending.subs ?? null,
    posts_week:        pending.posts_week ?? null,
    last_post_date:    pending.last_post_date ?? null,
  }
};

const routeData = $('OM: CODE Route Pending').first().json;
const session_id = routeData.session_id;
const _action = routeData._action;
let was_added = false;
let sources_count = routeData.sources_count;
try {
  const pgRow = $('OM: PG Append Source').first().json;
  was_added = pgRow.was_added === true;
  if (was_added) sources_count = pgRow.count;
} catch (_) {}
// status_text — НЕ менять
let status_text;
if (_action === 'skip') {
  status_text = ` Источников: ${sources_count}`;
} else if (was_added) {
  status_text = `✅ Канал добавлен. Источников: ${sources_count}`;
} else if (sources_count >= 10) {
  status_text = `🚫 Лимит 10 источников достигнут.`;
} else {
  status_text = `⚠️ Канал уже в списке. Источников: ${sources_count}`;
}
// Полная инфо для схлопнутой карточки
const subs  = routeData.subs ?? '—';
const posts = routeData.posts_week ?? '—';
const info  = `👥 Подписчиков: ${subs}\n📅 Постов за неделю: ${posts}`;
let previous_summary;
if (_action === 'skip') {
  previous_summary = `↩️ @${routeData.token} (пропущен)\n${info}`;
} else if (was_added) {
  previous_summary = `✅ @${routeData.token}\n${info}`;
} else if (sources_count >= 10) {
  previous_summary = `🚫 @${routeData.token} — лимит 10 достигнут`;
} else {
  previous_summary = `⚠️ @${routeData.token} — уже в списке`;
}
// Клавиатура — НЕ менять
const buttons = [];
if (sources_count >= 3) {
  buttons.push({ type: 'callback', text: '✓ Готово', payload: 'sources_done' });
}
const keyboard_override = buttons.length > 0 ? { buttons: [buttons] } : null;
// ← ЕДИНСТВЕННАЯ ПРАВКА: при достижении лимита показываем шаблон SOURCES_FULL
const next_step = sources_count >= 10 ? 'SOURCES_FULL' : 'SOURCES_INPUT';
return {
  json: { session_id, status_text, sources_count, keyboard_override, previous_summary, next_step }
};

const probe      = $('OM: CODE Parse Probe').first().json;
const validate   = $('OM: CODE Validate Source URL').first().json;
const session_id = Number($('OM: CODE Sources Router').first().json.session_id);
const token      = validate.token;

const text = [
  `📡 <b>${token}</b>`,
  `👥 Подписчиков: ${probe.subs ?? '—'}`,
  `📅 Постов за неделю: ${probe.posts_week}`,
`🕐 Последний пост: ${probe.last_post_date ? new Date(probe.last_post_date).toLocaleDateString('ru-RU') : '—'}`,
  '',
  'Добавить этот канал как источник?'
].join('\n');

const keyboard_override = {
  buttons: [[
    { type: 'callback', text: '✓ Добавить',   payload: `source_approve:${token}` },
    { type: 'callback', text: '✗ Пропустить', payload: `source_skip:${token}`    }
  ]]
};

return {
  json: {
    session_id,
    card_text: text,
    keyboard_override,
    previous_summary: `🔍 Проверяем канал @${token}`,
  }
};

