// HTTP-статус лежит в $json.error (AxiosError), не на корне item'а
const e = $json.error ?? {};
let code = Number(e.status ?? e.httpCode ?? e.response?.status) || 0;
if (!code) {                                   // фолбэк: вытащить "302" из текста
  const m = String(e.message ?? '').match(/\b(\d{3})\b/);
  if (m) code = Number(m[1]);
}

const deadCodes = [302, 403, 404, 410];
const _err_class = deadCodes.includes(code) ? 'dead' : 'infra';

let error_text_key;
if (code === 404 || code === 410) error_text_key = 'NOT_FOUND';
else if (code === 302 || code === 403) error_text_key = 'DEAD';
else error_text_key = 'INFRA_RETRY';

const router   = $('OM: CODE Sources Router').first().json;
const validate = $('OM: CODE Validate Source URL').first().json;

return { json: {
  _err_class,
  error_text_key,
  canon_url:     validate.canon_url,
  session_id:    Number(router.session_id),
  max_user_id:   router.max_user_id,
  http_code:     code,
  error_message: e.message ?? ''
}};

