const row = $json;
let ctx = row.context ?? {};
if (typeof ctx === 'string') { try { ctx = JSON.parse(ctx); } catch (_) { ctx = {}; } }

const rawSources = Array.isArray(ctx.sources) ? ctx.sources : [];
const sources = rawSources.map(s => ({
  url: s.url,
  last_processed_id: (s.last_processed_id == null || s.last_processed_id < 0)
    ? 0
    : s.last_processed_id
}));

const params = {
  user_id:           row.user_id ?? null,
  max_chat_id:       ctx.max_chat_id ?? null,
  title:             ctx.title ?? '',
  filter_prompt:     ctx.censor_prompt ?? '',
  generation_prompt: ctx.editor_prompt ?? '',
  posting_hours:     ctx.posting_hours ?? '',
  timezone:          ctx.timezone ?? 'Europe/Moscow',
  sources
};

const _valid =
  params.user_id != null &&
  params.max_chat_id != null &&
  sources.length >= 3;

return {
  json: {
    session: { id: row.id, user_id: row.user_id },
    params,
    _valid,
    _reason: _valid ? null : 'missing_required_fields'
  }
};

const src = $('OM: CODE Check FINAL_SAVE Result').first().json;
const p = src.params;

const usernames = (p.sources || [])
  .map(s => {
    const m = String(s.url).match(/t\.me\/s\/([a-z0-9_]+)/i);
    return m ? '@' + m[1] : null;
  })
  .filter(Boolean);

const sources_list = usernames.length ? usernames.join(', ') : '—';
const prompts_status = '✓ Фильтр настроен\n✓ Генерация настроена';

return {
  json: {
    session: src.session,
    dynamic_vars: {
      title:         p.title || '—',
      sources_list,
      posting_hours: p.posting_hours || '—',
      timezone:      p.timezone || '—',
      prompts_status
    }
  }
};

