const merged = $('OM: CODE Merge Final Data').first().json;
const normalized = merged.normalized;
const session = merged.session;
const payload = normalized.callback_payload || '';

const chMatch = payload.match(/^ch_(open|on|off)_(\d+)$/);
let menu_route;
if (payload === 'menu_my_channels')         menu_route = 'channels_list';
else if (payload === 'menu_create_channel') menu_route = 'create_channel';
else if (payload === 'menu_help')           menu_route = 'support';
else if (payload === 'support_contact')     menu_route = 'support';
else if (payload === 'menu_back')           menu_route = 'show_menu';
else if (chMatch && chMatch[1] === 'open')  menu_route = 'channel_card';
else if (chMatch && chMatch[1] === 'on')    menu_route = 'channel_on';
else if (chMatch && chMatch[1] === 'off')   menu_route = 'channel_off';
else                                        menu_route = 'show_menu';

const channel_id = chMatch ? parseInt(chMatch[2], 10) : null;
return { json: { normalized, session, menu_route, channel_id } };

// Передаём дальше — реальный подсчёт будет в PG ноде
// Здесь просто пробрасываем для единой точки входа в показ меню
return { json: { ...$json } };

const count = $('OM: PG Count Channels').first().json.channel_count || 0;
const session = $('OM: CODE Menu Router').first().json.session;

const next_step = count > 0 ? 'MAIN_MENU' : 'MAIN_MENU_EMPTY';

let subscription_end = '';
if (session.subscription_end) {
  const dt = new Date(session.subscription_end);
  subscription_end = '\n📅 Подписка до: ' + dt.toLocaleDateString('ru-RU');
}

const payload = JSON.stringify({
  next_step,
  skip_step_update: true,
  previous_summary: '↩️ В главное меню',
  dynamic_vars: { subscription_end }
});

return { json: { action: 'send_step', session_id: session.id, payload } };

const session = $('OM: CODE Prep FINAL_SAVE').first().json.session;

let subscription_end = '';
if (session.subscription_end) {
  const dt = new Date(session.subscription_end);
  subscription_end = '\n📅 Подписка до: ' + dt.toLocaleDateString('ru-RU');
}

const payload = JSON.stringify({
  next_step: 'MAIN_MENU',
  skip_step_update: true,
  close_previous: false,
  dynamic_vars: { subscription_end }
});
return { json: { action: 'send_step', session_id: session.id, payload } };

const rows = $input.all().map(i => i.json);
const session = $('OM: CODE Menu Router').first().json.session;

function badge(r) {
  if (r.status === 'moderation') return '🟡 модерация';
  if (r.status === 'rejected')   return '⛔ отклонён';
  return r.is_active ? '🟢 активен' : '⚪ выключен';
}

const buttons = rows.map(r => ([{
  text: `📢 ${r.title || 'без названия'} · ${badge(r)}`,
  type: 'callback', payload: `ch_open_${r.id}`, intent: 'default'
}]));
buttons.push([{ text: '⬅️ В меню', type: 'callback', payload: 'menu_back', intent: 'default' }]);

const payload = JSON.stringify({
  next_step: 'MENU_CHANNELS_LIST',
  skip_step_update: true,
  previous_summary: '✓ Мои каналы',
  keyboard_override: { buttons }
});
return { json: { action: 'send_step', session_id: session.id, payload } };

const ch = $('OM: PG Card Channel').first().json;
const srcRows = $('OM: PG Card Sources').all().map(i => i.json.source_url);
const session = $('OM: CODE Menu Router').first().json.session;


if (!ch || !ch.id) {
  const payload = JSON.stringify({
    next_step: 'MENU_CHANNELS_LIST', skip_step_update: true,
    previous_summary: '⚠️ Канал не найден',
    keyboard_override: { buttons: [[{ text:'⬅️ В меню', type:'callback', payload:'menu_back', intent:'default' }]] }
  });
  return { json: { action: 'send_step', session_id: session.id, payload } };
}

const statusMap = { moderation: '🟡 на модерации', approved: '✅ одобрен', rejected: '⛔ отклонён' };
const dynamic_vars = {
  title:             ch.title || 'без названия',
  max_chat_id:       ch.max_chat_id ?? '—',
  status:            statusMap[ch.status] || ch.status,
  is_active:         ch.is_active ? '🟢 включён' : '⚪ выключен',
  posting_hours:     ch.posting_hours || '—',
  timezone:          ch.timezone || '—',
  sources: srcRows.length ? srcRows.map(u => {
  const m = u.match(/t\.me\/s\/(\w+)/);
  return m ? '@' + m[1] : u;
}).join('\n') : '—',
  filter_prompt:     ch.filter_prompt || '—',
  generation_prompt: ch.generation_prompt || '—',
  created_at:        ch.created_at ? new Date(ch.created_at).toLocaleDateString('ru-RU') : '—'
};

const toggleBtn = ch.is_active
  ? { text: '⚪ Выключить', type:'callback', payload:`ch_off_${ch.id}`, intent:'negative' }
  : { text: '🟢 Включить',  type:'callback', payload:`ch_on_${ch.id}`,  intent:'positive' };

const keyboard_override = { buttons: [
  [toggleBtn],
  [{ text:'⬅️ Назад к списку', type:'callback', payload:'menu_my_channels', intent:'default' }]
]};

const route = $('OM: CODE Menu Router').first().json.menu_route;
let previous_summary = '✓ Открыт: ' + (ch.title || 'канал');
if (route === 'channel_on')  previous_summary = '✓ Канал включён';
if (route === 'channel_off') previous_summary = '✓ Канал выключен';

const payload = JSON.stringify({
  next_step: 'MENU_CHANNEL_CARD',
  skip_step_update: true,
  previous_summary,
  dynamic_vars,
  keyboard_override
});
return { json: { action:'send_step', session_id: session.id, payload } };

const session = $('OM: CODE Menu Router').first().json.session;
const channel_id = $('OM: CODE Menu Router').first().json.channel_id;
const payload = JSON.stringify({
  next_step: 'MENU_ACTIVATE_LIMIT',
  skip_step_update: true,
  previous_summary: '⚠️ Нет активных слотов',
  keyboard_override: { buttons: [
    [{ text:'💬 Связаться', type:'callback', payload:'support_contact', intent:'positive' }],
    [{ text:'⬅️ Назад', type:'callback', payload:`ch_open_${channel_id}`, intent:'default' }]
  ]}
});
return { json: { action:'send_step', session_id: session.id, payload } };

const session = $('OM: CODE Menu Router').first().json.session;
const payload = JSON.stringify({ next_step: 'CHANNEL_FORWARD_REQUEST', skip_step_update: true,
  previous_summary: '✓ Создание канала' });
return { json: { action: 'send_step', session_id: session.id, payload } };

const session = $('OM: CODE Menu Router').first().json.session;
const payload = JSON.stringify({
  next_step: 'MENU_CREATE_LIMIT', skip_step_update: true,
  previous_summary: '⚠️ Лимит каналов',
  keyboard_override: { buttons: [[{ text:'⬅️ В меню', type:'callback', payload:'menu_back', intent:'default' }]] }
});
return { json: { action: 'send_step', session_id: session.id, payload } };

const session = $('OM: CODE Menu Router').first().json.session;
const payload = JSON.stringify({
  next_step: 'SUPPORT_ASK', 
  skip_step_update: true,
  previous_summary: '✓ Поддержка',
  keyboard_override: { buttons: [[{ text:'⬅️ В меню', type:'callback', payload:'nav_menu', intent:'default' }]] }
});
return { json: { action: 'send_step', session_id: session.id, payload } };

const merged = $('OM: CODE Merge Final Data').first().json;
const n = merged.normalized;
const session = merged.session;
const data = {
  max_user_id: n.max_user_id,
  username:    n.username || '—',
  first_name:  n.first_name || '',
  text:        n.text || ''
};
return { json: {
  action: 'notify_admin',
  session_id: session.id,
  payload: JSON.stringify({ template_name: 'ADMIN_SUPPORT_REQUEST', data })
}};

const session = $('OM: CODE Merge Final Data').first().json.session;
const payload = JSON.stringify({
  next_step: 'SUPPORT_SENT',
  skip_step_update: true,
  previous_summary: '✓ Сообщение отправлено',
  keyboard_override: { buttons: [
    [{ text: '👋 Главное меню', type: 'callback', payload: 'nav_menu', intent: 'default' }]
  ]}
});
return { json: { action: 'send_step', session_id: session.id, payload } };

const r = $json;
const count = r.sources_count || 0;
const next_step = count >= 10 ? 'SOURCES_FULL' : 'SOURCES_INPUT';

const buttons = [];
if (count >= 3) buttons.push([{ text: '✅ Готово', type: 'callback', payload: 'sources_done', intent: 'positive' }]);

const payload = JSON.stringify({
  next_step,
  skip_step_update: true,
  previous_summary: '✓ Обновлено',
  dynamic_vars: { status_text: `Добавлено источников: ${count}`, error_text: '' },
  keyboard_override: buttons.length ? { buttons } : null
});
return { json: { action: 'send_step', session_id: r.session_id, payload } };
